const git=(...args)=>execFileSync('git',['-C',GIT,...args],{maxBuffer:MAX_SOURCE});
function free(){return Number(readFileSync('/sys/fs/cgroup/memory.max','utf8'))-Number(readFileSync('/sys/fs/cgroup/memory.current','utf8'));}
function room(){const n=free();if(n<MIN_FREE)throw new Error('NO_SLOT: cgroup free '+n+' < '+MIN_FREE);return n;}
const CONTENT=new Map();
const manifest=createHash('sha256').update(JSON.stringify(Object.entries(OVERLAY).map(([path,e])=>[path,e.sha]).sort((a,b)=>a[0]<b[0]?-1:a[0]>b[0]?1:0))).digest('hex');
if(Object.keys(OVERLAY).length!==14||manifest!=='724e8c702c00403c6aa8c5ba2f5f94fbc10fc888e09d5a63c5934f644f399428')throw new Error('M2910 snapshot manifest mismatch');
for(const[path,entry]of Object.entries(OVERLAY)){
 const data=entry.encoding==='base64'?Buffer.from(entry.content,'base64'):Buffer.from(entry.content,'utf8');
 const sha=createHash('sha1').update(Buffer.concat([Buffer.from('blob '+data.length+'\0'),data])).digest('hex');
 if(sha!==entry.sha)throw new Error('overlay blob mismatch '+path+' '+sha+' != '+entry.sha);
 CONTENT.set(path,data.toString('utf8'));
}
const names=new Set(git('ls-tree','-r','--name-only',TREE).toString().trim().split('\n'));
for(const path of Object.keys(OVERLAY))names.add(path);
const cache=new Map();let sourceBytes=0;
function source(path,before){
 const key=(before?'base:':'head:')+path;if(cache.has(key))return cache.get(key);
 const data=(OVERLAY[path]&&(!before||path.startsWith('tests/')))?CONTENT.get(path):git('show',TREE+':'+path).toString();
 sourceBytes+=Buffer.byteLength(data);if(sourceBytes>MAX_SOURCE)throw new Error('source budget exceeded');
 cache.set(key,data);return data;
}
