const config=await import('data:text/javascript,'+encodeURIComponent(CONTENT.get('tests/test-config.mjs')));
const aliases=Object.entries(config.testAliases('embed-library-unknown.test.ts',vr,vr+'/tests')).sort((a,b)=>b[0].length-a[0].length);
function resolvePath(path){return[path,path+'.ts',path+'.tsx',path+'.js',path+'.mjs',path+'/index.ts',path+'/index.tsx',path+'/index.js'].find(p=>names.has(p));}
function plugin(before){return{name:'pinned-2910-tree',setup(build){
 build.onResolve({filter:/^(?:@\/|\.\.?\/|next\/(?:headers|server)$)/},args=>{
  let candidate;
  for(const[from,to]of aliases)if(args.path===from||args.path.startsWith(from+'/')){
   if(typeof to==='string'&&to.startsWith(vr+'/'))candidate=to.slice(vr.length+1)+args.path.slice(from.length);
   else if(to===vr)candidate=args.path.slice(from.length).replace(/^\//,'');
   break;
  }
  if(candidate===undefined&&args.path.startsWith('@/'))candidate=args.path.slice(2);
  if(candidate===undefined&&args.namespace==='repo'&&args.path.startsWith('.'))candidate=posix.normalize(posix.join(posix.dirname(args.importer),args.path));
  if(candidate===undefined)return;
  const file=resolvePath(candidate);if(!file)throw new Error('pinned path not found '+candidate);
  return{path:file,namespace:'repo'};
 });
 build.onLoad({filter:/.*/,namespace:'repo'},args=>({contents:source(args.path,before),loader:args.path.endsWith('.tsx')?'tsx':args.path.endsWith('.json')?'json':'ts',resolveDir:DEPS}));
}};}
const bootstrap=(target)=>`
import {store as redis} from "@/tests/redis-stub";
let active=1,total=0,depth=0,attempts=0,capped=false;
const cases=new Map(JSON.parse(process.env.M2910_PRIOR_COMMANDS??'[]'));
total=[...cases.values()].reduce((sum,n)=>sum+n,0);
function wrap(fn){return function(batch){
 if(depth===0){const n=batch.length;const next=(cases.get(active)||0)+n;if(next>3000||total+n>18000){capped=true;throw new Error("M2910_COMMAND_CAP before dispatch");}cases.set(active,next);total+=n;}
 depth++;try{return fn.call(redis,batch);}finally{depth--;}
};}
let current=wrap(redis.pipeline.bind(redis));
Object.defineProperty(redis,"pipeline",{configurable:false,get(){return current;},set(fn){current=wrap(fn);}});
globalThis.__m2910Case=(n)=>{if(!Number.isInteger(n)||n<1||n>6)throw new Error("M2910_CASE_CAP");active=n;};
Object.defineProperty(globalThis,"fetch",{configurable:false,get(){return async()=>{attempts++;throw new Error("M2910 external fetch blocked");};},set(_fn){}});
process.on("exit",()=>{if(capped||attempts)process.exitCode=1;console.log("M2910_CAP:"+JSON.stringify({total,cases:[...cases],fetchAttempts:attempts,capped}));});
Promise.resolve().then(()=>import("${target}")).catch(e=>{console.error("M2910_IMPORT_ERROR",e);process.exitCode=1;});
`;
