  const run=spawnSync(process.execPath,['--max-old-space-size=512',bundle],{cwd:DEPS,env:clean,encoding:'utf8',timeout:remaining,maxBuffer:Math.max(1,MAX_LOG-logBytes)});
  emit('M2910_RUN:'+JSON.stringify({mode,before,pin:before?BASE:HEAD,tree:TREE,freeBeforeBuild:available,status:run.status,signal:run.signal,error:run.error?.message,sourceBytes})+'\n');
