  const receipt=JSON.parse(receipts[0].slice('M2910_CAP:'.length));
  if(!Array.isArray(receipt.cases)||receipt.cases.length>6||!Number.isSafeInteger(receipt.total)||receipt.total<0||receipt.total>18000||receipt.fetchAttempts!==0||receipt.capped!==false)throw new Error('M2910 cap receipt unknown or failed');
  const seen=new Set();let sum=0;
  for(const row of receipt.cases){if(!Array.isArray(row)||row.length!==2||!Number.isInteger(row[0])||row[0]<1||row[0]>6||seen.has(row[0])||!Number.isSafeInteger(row[1])||row[1]<0||row[1]>3000)throw new Error('M2910 per-case receipt invalid');seen.add(row[0]);sum+=row[1];}
  if(sum!==receipt.total||priorCases.some(([id,count])=>!receipt.cases.some(([nextId,next])=>nextId===id&&next>=count)))throw new Error('M2910 cap totals lost prior work');
  priorCases=receipt.cases;
